					r->ar.start, min_region_sz);
			if (!sz_to_skip) {
				if (damon_sz_region(r) <= min_region_sz)
					return true;
				sz_to_skip = min_region_sz;
			}
			damon_split_region_at(t, r, sz_to_skip);
			return true;
		}
		quota->charge_target_from = NULL;
		quota->charge_addr_from = 0;
	}
	return false;
}

