 */
int damos_walk(struct damon_ctx *ctx, struct damos_walk_control *control)
{
	init_completion(&control->completion);
	control->canceled = false;
	mutex_lock(&ctx->walk_control_lock);
	if (ctx->walk_control) {
		mutex_unlock(&ctx->walk_control_lock);
